import test from 'node:test';import assert from 'node:assert/strict';import {rocketWorld,rocketObjects,rocketLinks,normalizeRocketLab,rocketAction,rocketView,rocketCanLaunch,rocketThrustResult,rocketArtKeys,rocketArt,rocketPanelSvg,rocketPreviewPose,rocketWorldPose} from '../src/rocket-lab.js';import {normalizeMachines,machineCommand,machineReady} from '../src/machines.js';import {objects,materials} from '../src/data.js';import {zones,zoneExit} from '../src/zones.js';import {pathfind,cellAt,blocked} from '../src/navigation.js';import {getJournalEntries} from '../src/journal.js';
function garage(){let s=normalizeMachines();s=machineCommand(s,{type:'blueprint',value:'rocket'}).machines;s=machineCommand(s,{type:'part',slot:'motion',value:'vector'}).machines;s=machineCommand(s,{type:'part',slot:'module',value:'cargo'}).machines;s=machineCommand(s,{type:'color',value:'orange'}).machines;s=machineCommand(s,{type:'helper'}).machines;s=machineCommand(s,{type:'save'}).machines;return s;}
const ctx=()=>({rockets:garage().models});
function ready(){const c=ctx();let s=rocketAction({}, {type:'choose',id:'m1'},c).lab;s=rocketAction(s,{type:'pip-check'},c).lab;return s;}
test('all new entrances and station approaches are separate and reachable around solid benches',()=>{const targets=[...rocketObjects,...rocketLinks,objects.find(o=>o.id==='rocketlab-exit')];for(const o of targets){const to=[o.x-65,o.y+55];assert.ok(pathfind(zones[o.zone].spawn,to,o.zone).length||cellAt(...zones[o.zone].spawn,o.zone).join()===cellAt(...to,o.zone).join(),o.id);for(const p of objects.filter(p=>p.zone===o.zone&&p.id!==o.id))assert.ok(Math.abs(o.x-p.x)>=94||Math.abs(o.y-p.y)>=70,o.id+' overlaps '+p.id);}assert.ok(blocked(6,6,'rocketlab'));assert.equal(blocked(9,6,'rocketlab'),false);assert.equal(zoneExit('grounds','rocketlab'),'grounds-rocketlab');assert.equal(zoneExit('hq','rocketlab'),'hq-rocketlab');assert.equal(zoneExit('engineering','rocketlab'),'yard-rocketlab');assert.equal(zoneExit('rocketlab','hq'),'rocketlab-hq');assert.equal(zoneExit('rocketlab','grounds'),'rocketlab-exit');assert.equal(rocketWorld.rocketlab.chapter,true);});
test('only an owned complete rocket can pass launch checks, and its flight copy retains custom parts',()=>{const c=ctx();assert.equal(rocketCanLaunch(normalizeRocketLab(),c),false);assert.equal(rocketAction({}, {type:'launch'},c).route,'choose:0');let s=rocketAction({}, {type:'choose',id:'m1'},c).lab;assert.equal(s.snapshot.parts.motion,'vector');assert.equal(s.snapshot.parts.module,'cargo');assert.equal(s.snapshot.color,'orange');assert.equal(s.phase,0);c.rockets[0].parts.motion='nozzle';assert.equal(s.snapshot.parts.motion,'vector');s=rocketAction(s,{type:'check',id:'computer'},c).lab;assert.deepEqual(s.checks,['computer']);assert.equal(rocketView(s,'checks',c).art,'checks-4');assert.equal(rocketCanLaunch(s,c),false);s=rocketAction(s,{type:'pip-check'},c).lab;assert.ok(rocketCanLaunch(s,c));assert.ok(s.completed.includes('checks'));assert.equal(rocketAction(s,{type:'launch'},{rockets:[]}).route,'choose:0');});
test('flights wait for explicit taps, persist mid-flight, record only reports, and repeat without consuming anything',()=>{const c=ctx(),before=JSON.stringify(c);let s=ready();s=rocketAction(s,{type:'launch'},c).lab;assert.equal(s.phase,1);assert.equal(s.completed.includes('launch'),false);assert.deepEqual(normalizeRocketLab(JSON.parse(JSON.stringify(s))),s);s=rocketAction(s,{type:'next'},c).lab;assert.equal(s.phase,2);assert.notDeepEqual(rocketWorldPose(1),rocketWorldPose(2));assert.notDeepEqual(rocketPreviewPose(1),rocketPreviewPose(2));s=rocketAction(s,{type:'next'},c).lab;assert.equal(s.phase,3);assert.deepEqual(s.flown,[]);s=rocketAction(s,{type:'next'},c).lab;assert.equal(s.phase,4);assert.deepEqual(s.flown,['orbit']);assert.ok(s.completed.includes('launch'));for(let n=0;n<3;n++){s=rocketAction(s,{type:'repeat'},c).lab;s=rocketAction(s,{type:'launch'},c).lab;for(let k=0;k<3;k++)s=rocketAction(s,{type:'next'},c).lab;}assert.equal(s.flown.length,1);assert.equal(JSON.stringify(c),before);s=rocketAction(s,{type:'mission',id:'moon'},c).lab;assert.equal(s.phase,0);assert.ok(!s.checks.includes('computer'));assert.ok(s.checks.includes('structure'));assert.equal(s.mission,'moon');});
test('thrust responds to force and payload while vacuum does not remove rocket propulsion',()=>{let s=normalizeRocketLab();assert.equal(rocketThrustResult(s),'rise');s=rocketAction(s,{type:'demo',id:'mass'}).lab;assert.equal(rocketThrustResult(s),'balance');s=rocketAction(s,{type:'demo',id:'mass'}).lab;assert.equal(rocketThrustResult(s),'wait');s=rocketAction(s,{type:'demo',id:'run'}).lab;assert.ok(s.completed.includes('thrust'));s=rocketAction(s,{type:'demo',id:'air'}).lab;assert.equal(s.vacuum,true);assert.equal(rocketThrustResult(s),'wait');s=rocketAction(s,{type:'demo',id:'thrust'}).lab;s=rocketAction(s,{type:'demo',id:'mass'}).lab;assert.equal(rocketThrustResult(s),'rise');assert.match(rocketView(s,'demo').text,/air or vacuum/);});
test('sky observations and mission discoveries journal actual activity and point to the correct repeated science',()=>{let s=normalizeRocketLab();const blank=getJournalEntries('experiments',new Set(),new Set(['rocketlab-test']),objects,materials);assert.equal(blank.length,0);s=rocketAction(s,{type:'sky',id:'observe'}).lab;s=rocketAction(s,{type:'sky',id:'next'}).lab;s=rocketAction(s,{type:'sky',id:'observe'}).lab;const found=getJournalEntries('found',new Set(),new Set(),objects,materials,{},{},{},{},{},{},{},s);assert.equal(found.length,2);assert.deepEqual(found.map(e=>e.rocketSky),[0,1]);assert.equal(found[0].target,'rocketlab-sky');let flight=ready();flight=rocketAction(flight,{type:'launch'},ctx()).lab;for(let k=0;k<3;k++)flight=rocketAction(flight,{type:'next'},ctx()).lab;assert.equal(getJournalEntries('adventures',new Set(),new Set(),objects,materials,{},{},{},{},{},{},{},flight)[0].id,'rocket-mission-orbit');assert.equal(getJournalEntries('experiments',new Set(),new Set(),objects,materials,{},{},{},{},{},{},{},flight).length,2);});
test('bounded saves and every menu/art state fit the native presentation',()=>{assert.deepEqual(normalizeRocketLab(null),normalizeRocketLab());assert.equal(normalizeRocketLab({snapshot:{type:'rocket'},vehicleId:'m1',checks:{},phase:2}).phase,0);const c=ctx(),s=ready();s.phase=4;for(const bad of [null,{},3,'structure'])assert.doesNotThrow(()=>normalizeRocketLab({...s,checks:bad}));assert.equal(normalizeRocketLab({...s,phase:99,sky:99,thrust:8}).phase,0);const pages=['home','professor','chen','garage','choose:0','missions','prepare','checks','flight','report','demo','sky','help'];for(let phase=0;phase<=4;phase++){s.phase=phase;for(const page of pages){const v=rocketView(s,page,c);assert.ok(v.actions.length<=5,page);assert.ok(v.text.replace(/(.{1,43})(?:\s|$)/g,'$1\n').trim().split('\n').length<=7,page+': '+v.text);assert.ok(rocketArtKeys.includes(v.art),v.art);assert.match(rocketPanelSvg(v),/<svg/);}}for(const key of rocketArtKeys)assert.match(rocketArt(key),/<svg/);assert.notEqual(rocketArt('checks-1'),rocketArt('checks-4'));assert.match(rocketView(s,'chen').text,/China/);});
